```sparql
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>

SELECT DISTINCT ?relative WHERE {
  {
    # How many relatives are there of the people who died in Germany?
    ?person dbo:deathPlace dbr:Germany .
    ?person dbo:relative ?relative .
  }
  UNION
  {
    # Who is relative of the people died in Bergen-Belsen concentration camp?
    ?person dbo:deathPlace dbr:Bergen-Belsen_concentration_camp .
    ?person dbo:relative ?relative .
  }
  UNION
  {
    # With whom is Heinz Kokott related who also served in Nazi Army?
    dbr:Heinz_Kokott dbo:relation ?relative .
    ?relative a dbo:MilitaryPerson .
    ?relative dbo:militaryBranch ?militaryBranch .
    FILTER(CONTAINS(LCASE(STR(?militaryBranch)), "nazi") || CONTAINS(LCASE(STR(?militaryBranch)), "wehrmacht"))
  }
}
```

