```SELECT DISTINCT ?river ?question WHERE {
  VALUES ?question {
    "Was Zambezi originate in the north western province of zambia?"
    "Name the river whose mouth country is Mozambique and source region is North-Western Province, Zambia?"
    "What are some rivers in Zambia which have a dam on them?"
  }
  BIND (
    IF(?question = "Was Zambezi originate in the north western province of zambia?", "ask",
      IF(?question = "Name the river whose mouth country is Mozambique and source region is North-Western Province, Zambia?", "query1",
        IF(?question = "What are some rivers in Zambia which have a dam on them?", "query2", "none")
      )
    ) AS ?queryType
  )
  FILTER(?queryType != "none")
  {
    # Query for "Was Zambezi originate in the north western province of zambia?"
    FILTER(?queryType = "ask")
    BIND(<http://dbpedia.org/resource/Zambezi> AS ?river)
    FILTER EXISTS {
      <http://dbpedia.org/resource/Zambezi> <http://dbpedia.org/property/sourceRegion> <http://dbpedia.org/resource/North-Western_Province,_Zambia> 
    }
  }
  UNION
  {
    # Query for "Name the river whose mouth country is Mozambique and source region is North-Western Province, Zambia?"
    FILTER(?queryType = "query1")
    ?river <http://dbpedia.org/property/mouthCountry> <http://dbpedia.org/resource/Mozambique> .
    ?river <http://dbpedia.org/property/sourceRegion> <http://dbpedia.org/resource/North-Western_Province,_Zambia> .
    ?river a <http://dbpedia.org/ontology/River> .
  }
  UNION
  {
    # Query for "What are some rivers in Zambia which have a dam on them?"
    FILTER(?queryType = "query2")
    ?dam a <http://dbpedia.org/ontology/Dam> .
    ?dam <http://dbpedia.org/property/river> ?river .
    ?river <http://dbpedia.org/property/country> <http://dbpedia.org/resource/Zambia> .
  }
}
