        OPTIONAL
          { FILTER ( ?ship = <http://dbpedia.org/resource/NOAAS_Davidson_(S_331)> )
            BIND(EXISTS { <http://dbpedia.org/resource/NOAAS_Davidson_(S_331)>
                                    <http://dbpedia.org/ontology/homeport>  <http://dbpedia.org/resource/Seattle>
                        } AS ?hasSeattleHomeport)
          }
      }
    UNION
      { ?river  <http://dbpedia.org/ontology/riverMouth>  <http://dbpedia.org/resource/Indian_Ocean> ;
                <http://dbpedia.org/ontology/sourceCountry>  <http://dbpedia.org/resource/Zambia> ;
                rdf:type              <http://dbpedia.org/ontology/River>
      }
  }

