SELECT DISTINCT ?homeport ?hasSeattleHomeport ?river WHERE {
  {
    VALUES (?ship) { (<http://dbpedia.org/resource/INS_Viraat_(R22)>) (<http://dbpedia.org/resource/NOAAS_Davidson_(S_331)>) }
    OPTIONAL {
